se":true,"coreVoidNotes":["变用坤卦未位逢空，申位未空，按半空减力，仍参与体用判断。"],"ruleVersions":{"void":"trigram-void-2.1.0","decision":"interview-evidence-1.0.0"},"voidReleaseSpecs":[],"voidTimingSlots":[],"voidTimingText":"","lineApplication":{"evidence":["田获三狐","得黄矢","贞吉"],"conditions":["不把三狐移植成三位面试官、三轮面试或三个录用机会"]},"counterevidence":[{"fact":"初用与体互均生体，动爻有贞吉","resolution":"生体水皆死助弱、体木囚难制末用旺土；保留贞吉的守正与排疑益处，取当前通过支撑不足。"}],"sourceIds":["mh-056","mh-058","mh-071","mh-101","mh-116","mh-117","mh-119","mh-143","user-void-extension","user-void-timing"],"review":{"status":"author-checked","actor":"assistant-author","version":"interview-pass-1.2.0","scope":"base-prose-and-recorded-void-profile;equivalent-qi-month-slots-share-written-text;exempt-core-void-does-not-change-verdict","verification":"computed-facts-plus-authored-judgment;not-independent-human-expert-certification","independentReview":{"status":"pending","timingInterpretation":"pending","calendarConversion":"separate-technical-check","userAcceptedThisVersion":false},"checks":{"chart-and-moving-line":{"status":"pass","scope":"author-check-only;not-independent-approval","evidence":[{"sourceId":"project-interview-authoring","locator":"40/2","reason":"Canonical six-line, mutual and one-line change recalculation"}]},"body-use-position":{"status":"pass","scope":"author-check-only;not-independent-approval","evidence":[{"sourceId":"project-interview-authoring","locator":"canonical-role-assignment","reason":"Original body is retained in all three stages"}]},"question-method-match":{"status":"pass","scope":"author-check-only;not-independent-approval","evidence":[{"sourceId":"project-interview-authoring","locator":"mh-071;project-interview-stage-application-v1","reason":"Fame chapter applied to this interview stage, separate from offer"}]},"relation-directions":{"status":"pass","scope":"author-check-only;not-independent-approval","evidence":[{"sourceId":"project-interview-authoring","locator":"facts.directRelations","reason":"Four direct relations in