neratingRoles":["changed_use"],"movingLineAdverseTerms":true,"noGenerationWithUseControl":false,"reliefIsNotAttainment":null,"authorResolution":[{"fact":"体土相、两木休克较弱、末后旺火生体，结构有明显改善","resolution":"明示改善，不忽略旺火；完整上六以失遇过越为核心且明确凶，取当前轮次不利而补救有援，不推断现实灾害。"}],"independentReviewStatus":"pending"},"indirectEffectsApplied":[],"interpretationProvenance":"assistant-authored;not-observed-feedback;not-scientifically-verified-prediction"},"copy":{"title":"后面虽有帮助，这一轮仍不宜乐观","short":{"decisionId":"career.interview.interview-pass/62/6/summer-fire/not-pass-this-round","text":"这轮面试仍倾向难以通过，但后段有帮助，事情并非一直受阻。开头和中间的问题需要认真处理，眼下不宜急着强推一个答复。把反馈落实到具体要求上，能修正的及时改；应期留意本轮受阻或不利反馈，再安排后续争取。"},"long":{"decisionId":"career.interview.interview-pass/62/6/summer-fire/not-pass-this-round","opening":"起初有压力，但尚有承接条件。艮土体夏令属相，震木用属休而克体，牵制较弱，回应要求仍有余地。宜按事实说明，不急于把话说满。","process":"中间还有需要处理的问题。体互巽木属休，继续克体，压力仍在；用互兑金属死，受体土所生，耗费相对较轻。把追问答清，有利于减少误解。","ending":"上六“弗遇过之；飞鸟离之，凶，是谓灾眚”，对眼下失遇、过越给出明确警戒。变用离火当旺，来生体，末后帮助较实，可用于修正和补救。这一轮仍取难过，不宜把补救机会当作已定的通过。","summary":"本轮仍偏难过，末后有补救余地。把帮助用来核对承诺与条件，先守住能够承担的范围。"}},"timingSlots":[{"id":"result","kind":"control","role":"use","event":"本轮面试推进受阻或收到不利反馈","valence":"凶","ruleIds":["adverse-event"],"sourceIds":["mh-116","mh-143"],"prefix":"留意","suffix":"前后的本轮面试进展，推进受阻或出现不利反馈的意味较重，属凶应。","eventScope":"obstruction-or-adverse-result","calculationBasis":{"role":"use","trigram":"震","element":"木","directRelation":"use_controls_body","method":"pre-heaven-element-qi","scale":"day","ruleIds":["adverse-event"],"sourceIds":["mh-116","mh-143"],"interpretationReview":"author-source-checked","independentInterpretationReview":"pending"},"token":"{{date:result}}","branches":["寅","卯"],"displayLimit":2,"method":"element-qi","scale":"day","emptyText":"本次可显示范围内暂无相应候选日期。"}],"baseProse":true,"coreVoidNotes":["变用离卦逢空，但本身发动，仍有作用。"],"ruleVersions":{"void":"trigram-void-2.1.0","decision":"interview-evidence-1.0.0"},"voidReleaseSpecs":[],"voidTimingSlots":[],"voidTimingText":"","lineApplication":{"evidence":["弗遇过之","飞鸟离之","凶","是谓灾