UseControl":false,"reliefIsNotAttainment":null,"authorResolution":[{"fact":"旺土体可承接囚木克与相金耗，变用火休生体","resolution":"完整保留较好的承接与末后帮助；上六对当前轮次明确失遇凶意，取本轮不利而调整有条件，不说所有帮助失效。"}],"independentReviewStatus":"pending"},"indirectEffectsApplied":[],"interpretationProvenance":"assistant-authored;not-observed-feedback;not-scientifically-verified-prediction"},"copy":{"title":"有应对余地，当前结果仍宜谨慎","short":{"decisionId":"career.interview.interview-pass/62/6/seasonal-earth/not-pass-this-round","text":"这轮面试仍倾向难以通过，但你有承接要求的基础，后段也有帮助。眼下宜把不合适的回答和做法调整清楚，别只急于推动结果。应期关注本轮受阻或不利反馈，拿到具体意见后再修正准备，继续争取后续机会。"},"long":{"decisionId":"career.interview.interview-pass/62/6/seasonal-earth/not-pass-this-round","opening":"开头有压力，仍有应对余地。艮土体土令当旺，震木用属囚而克体，牵制较弱，已明确的要求可以认真处理，不必因追问就急着改变所有说法。","process":"中间仍需花精力。体互巽木属囚，继续克体，压力有限；用互兑金属相，受体土所生，补充说明有耗费，但体土尚有承接条件。宜把关键问题答清，再核对尚未明确的要求。","ending":"上六“弗遇过之；飞鸟离之，凶，是谓灾眚”，重点警戒当前失遇、过越。变用离火属休，来生体，末后有帮助，可接住来修正问题。就眼下这一轮，仍取通过偏难。","summary":"本轮仍不宜乐观，但有修正余地。把帮助用在收拢过度争取上，守住能力边界，再考虑下一次安排。"}},"timingSlots":[{"id":"result","kind":"control","role":"use","event":"本轮面试推进受阻或收到不利反馈","valence":"凶","ruleIds":["adverse-event"],"sourceIds":["mh-116","mh-143"],"prefix":"留意","suffix":"前后的本轮面试进展，推进受阻或出现不利反馈的意味较重，属凶应。","eventScope":"obstruction-or-adverse-result","calculationBasis":{"role":"use","trigram":"震","element":"木","directRelation":"use_controls_body","method":"pre-heaven-element-qi","scale":"day","ruleIds":["adverse-event"],"sourceIds":["mh-116","mh-143"],"interpretationReview":"author-source-checked","independentInterpretationReview":"pending"},"token":"{{date:result}}","branches":["寅","卯"],"displayLimit":2,"method":"element-qi","scale":"day","emptyText":"本次可显示范围内暂无相应候选日期。"}],"baseProse":true,"coreVoidNotes":["变用离卦逢空，但本身发动，仍有作用。"],"ruleVersions":{"void":"trigram-void-2.1.0","decision":"interview-evidence-1.0.0"},"voidReleaseSpecs":[],"voidTimingSlots":[],"voidTimingText":"","lineApplication":{"evidence":["弗遇过之","飞鸟离之","凶","是谓灾眚"],"conditions":["不编造面试真实经过，不把灾眚扩成现实人身灾害"]},"counterevidence":[{"fact":"旺